contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount to deposit into c before attempting withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // Observe contract balance before deposit
        uint beforeBalance = address(c).balance;

        // Perform deposit as a top-level state-changing call on c (may be zero)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Observe contract balance after deposit
        uint afterDepositBalance = address(c).balance;

        // Attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe contract balance after withdraw attempt
        uint afterWithdrawBalance = address(c).balance;

        // Compute observable increase caused by our deposit (no underflow: afterDepositBalance >= beforeBalance)
        uint observedIncrease = afterDepositBalance >= beforeBalance ? afterDepositBalance - beforeBalance : 0;

        // Compute observable decrease caused by withdraw attempt (no underflow guard)
        uint observedDecrease = afterDepositBalance >= afterWithdrawBalance ? afterDepositBalance - afterWithdrawBalance : 0;

        // Single general assertion: if withdrawAll did not revert then the observed decrease equals the observed increase;
        // if it reverted, nothing is required (we still assert that reverted==true implies observedDecrease == 0 OR arbitrary —
        // to keep a single assert, we express the property as: either it reverted, or decrease equals increase).
        assert(reverted || (observedDecrease == observedIncrease));
    }

    receive() external payable {}
}

